local decal = Instance.new("ImageLabel", main)
decal.Size = UDim2.new(0, 100, 0, 100)
decal.Position = UDim2.new(0, -110, 0, 80)
decal.Image = "rbxassetid://98927618057039" -- เปลี่ยนเป็น ID ของคุณ
decal.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
decal.BorderColor3 = Color3.fromRGB(0, 170, 255)


local scroll = Instance.new("ScrollingFrame", main)
scroll.Size = UDim2.new(1, -20, 1, -80)
scroll.Position = UDim2.new(0, 10, 0, 80)
scroll.CanvasSize = UDim2.new(0, 0, 0, 1000)
scroll.ScrollBarThickness = 10
scroll.BackgroundTransparency = 1
scroll.BorderColor3 = Color3.fromRGB(0, 170, 255)


local UIGridLayout = Instance.new("UIGridLayout", scroll)
UIGridLayout.CellSize = UDim2.new(0, 150, 0, 40)
UIGridLayout.CellPadding = UDim2.new(0, 10, 0, 10)


local function getRainbowColor(offset)
	local hue = (tick() * 0.15 + offset) % 1
	return Color3.fromHSV(hue, 1, 1)
end


local buttonCount = 0
function createButton(name, callback)
	buttonCount += 1
	local btn = Instance.new("TextButton", scroll)
	btn.Name = name
	btn.Size = UDim2.new(0, 150, 0, 40)
	btn.Text = name
	btn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
	btn.BorderColor3 = Color3.fromRGB(0, 170, 255)
	btn.Font = Enum.Font.FredokaOne
	btn.TextScaled = true
	btn.TextColor3 = getRainbowColor(buttonCount * 0.1)

	btn.MouseButton1Click:Connect(callback)
end


